class MedianFinder {
    private var smallHeap: [Int] = []  // maxHeap for small elements
    private var largeHeap: [Int] = []  // minHeap for large elements

    func addNum(_ num: Int) {
        // Add to maxHeap (smallHeap)
        smallHeap.append(num)
        heapifyUpMax(&smallHeap, smallHeap.count - 1)

        // Balance: check if max of small > min of large
        if !largeHeap.isEmpty && smallHeap[0] > largeHeap[0] {
            let val = extractMax(&smallHeap)
            largeHeap.append(val)
            heapifyUpMin(&largeHeap, largeHeap.count - 1)
        }

        // Balance sizes
        if smallHeap.count - largeHeap.count > 1 {
            let val = extractMax(&smallHeap)
            largeHeap.append(val)
            heapifyUpMin(&largeHeap, largeHeap.count - 1)
        }
        if largeHeap.count - smallHeap.count > 1 {
            let val = extractMin(&largeHeap)
            smallHeap.append(val)
            heapifyUpMax(&smallHeap, smallHeap.count - 1)
        }
    }

    func findMedian() -> Double {
        if smallHeap.count == largeHeap.count {
            return Double(largeHeap[0] + smallHeap[0]) / 2.0
        } else if smallHeap.count > largeHeap.count {
            return Double(smallHeap[0])
        } else {
            return Double(largeHeap[0])
        }
    }

    // Max-heap operations
    private func heapifyUpMax(_ heap: inout [Int], _ index: Int) {
        var i = index
        while i > 0 {
            let parent = (i - 1) / 2
            if heap[i] > heap[parent] {
                heap.swapAt(i, parent)
                i = parent
            } else {
                break
            }
        }
    }

    private func heapifyDownMax(_ heap: inout [Int], _ index: Int) {
        var i = index
        while true {
            let left = 2 * i + 1
            let right = 2 * i + 2
            var largest = i
            if left < heap.count && heap[left] > heap[largest] {
                largest = left
            }
            if right < heap.count && heap[right] > heap[largest] {
                largest = right
            }
            if largest != i {
                heap.swapAt(i, largest)
                i = largest
            } else {
                break
            }
        }
    }

    private func extractMax(_ heap: inout [Int]) -> Int {
        let max = heap[0]
        heap[0] = heap.removeLast()
        if !heap.isEmpty {
            heapifyDownMax(&heap, 0)
        }
        return max
    }

    // Min-heap operations
    private func heapifyUpMin(_ heap: inout [Int], _ index: Int) {
        var i = index
        while i > 0 {
            let parent = (i - 1) / 2
            if heap[i] < heap[parent] {
                heap.swapAt(i, parent)
                i = parent
            } else {
                break
            }
        }
    }

    private func heapifyDownMin(_ heap: inout [Int], _ index: Int) {
        var i = index
        while true {
            let left = 2 * i + 1
            let right = 2 * i + 2
            var smallest = i
            if left < heap.count && heap[left] < heap[smallest] {
                smallest = left
            }
            if right < heap.count && heap[right] < heap[smallest] {
                smallest = right
            }
            if smallest != i {
                heap.swapAt(i, smallest)
                i = smallest
            } else {
                break
            }
        }
    }

    private func extractMin(_ heap: inout [Int]) -> Int {
        let min = heap[0]
        heap[0] = heap.removeLast()
        if !heap.isEmpty {
            heapifyDownMin(&heap, 0)
        }
        return min
    }
}

