use std::cmp::Reverse;
use std::collections::BinaryHeap;

struct MedianFinder {
    small_heap: BinaryHeap<i32>,           // max heap for smaller elements
    large_heap: BinaryHeap<Reverse<i32>>,  // min heap for larger elements
}

impl MedianFinder {
    pub fn new() -> Self {
        MedianFinder {
            small_heap: BinaryHeap::new(),
            large_heap: BinaryHeap::new(),
        }
    }

    pub fn add_num(&mut self, num: i32) {
        self.small_heap.push(num);

        // Ensure max of small_heap <= min of large_heap
        if !self.large_heap.is_empty() && !self.small_heap.is_empty() {
            if let (Some(&small_max), Some(&Reverse(large_min))) =
                (self.small_heap.peek(), self.large_heap.peek())
            {
                if small_max > large_min {
                    self.large_heap.push(Reverse(self.small_heap.pop().unwrap()));
                }
            }
        }

        // Balance the heaps
        if self.small_heap.len() > self.large_heap.len() + 1 {
            self.large_heap.push(Reverse(self.small_heap.pop().unwrap()));
        }
        if self.large_heap.len() > self.small_heap.len() + 1 {
            self.small_heap.push(self.large_heap.pop().unwrap().0);
        }
    }

    pub fn find_median(&self) -> f64 {
        if self.small_heap.len() == self.large_heap.len() {
            let small_max = *self.small_heap.peek().unwrap() as f64;
            let large_min = self.large_heap.peek().unwrap().0 as f64;
            (small_max + large_min) / 2.0
        } else if self.small_heap.len() > self.large_heap.len() {
            *self.small_heap.peek().unwrap() as f64
        } else {
            self.large_heap.peek().unwrap().0 as f64
        }
    }
}

